class VocabularyScreen extends StatefulWidget { const VocabularyScreen({super.key}); @override State<VocabularyScreen> createState()=>_VocabularyScreenState(); }
class _VocabularyScreenState extends State<VocabularyScreen>{String query='';@override Widget build(BuildContext context){final filtered=words.where((w)=>'${w.hanzi}${w.pinyin}${w.meaning}'.toLowerCase().contains(query.toLowerCase())).toList();return SafeArea(child:Column(children:[const ScreenHeader(eyebrow:'Bộ nhớ cá nhân',title:'Từ vựng'),Padding(padding:const EdgeInsets.fromLTRB(20,0,20,14),child:TextField(onChanged:(v)=>setState(()=>query=v),decoration:InputDecoration(hintText:'Tìm Hán tự, pinyin hoặc nghĩa...',prefixIcon:const Icon(Icons.search),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none)))),Expanded(child:ListView.separated(padding:const EdgeInsets.fromLTRB(20,0,20,24),itemCount:filtered.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(context,index){final w=filtered[index];return Card(child:Padding(padding:const EdgeInsets.all(15),child:Row(children:[HanziAvatar(w.hanzi,size:58,color:const Color(0xFFFFEDE4)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(w.pinyin,style:const TextStyle(color:AppTheme.red,fontWeight:FontWeight.w700)),Text(w.meaning,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(w.example,style:const TextStyle(color:Colors.grey,fontSize:11))])),IconButton(onPressed:(){},icon:const Icon(Icons.bookmark_rounded,color:AppTheme.jade))])));}))]));}}
